function initPalette() {
    paletteNumber = int(random(palettes.length));
    let paletteRand = palettes[paletteNumber];

    PALETTE = {
        back: random(paletteRand.backColors),
        rectColors: paletteRand.rectColors,
        arcColors: paletteRand.arcColors,
        outlineColor: random(paletteRand.outlineColors)
    }
}


function initArcs() {
    let segmentNum = 0;
    let colors = shuffle([...PALETTE.arcColors]);
    segments.forEach(segment => {
        for (let i = 1; i <= numArcs[segmentNum]; i++) {
            let x = fl(randomGaussian((segment.x + segment.w * 0.5), segment.w / sdDivider));
            let y = fl(randomGaussian((segment.y + segment.h * 0.5), segment.h / sdDivider));

            let angle = random(TWO_PI);
            let arcWidth;
            arcWidth = fl(minSide * random(0.1, 0.24) * (i / (numArcs[segmentNum])) * (1 - segments.length * 0.14));
            arcWidth = max(arcWidth, minSide * 0.02);

            let r = fl(arcWidth * random([0, random(0.1, 0.5)]));
            let start = random(TWO_PI);
            arcWidth -= r;
            let stop = start + random([PI / 2, PI, PI + PI / 5, PI + PI / 4, PI + PI / 3, PI + PI / 2,
                TWO_PI + PI / 6, TWO_PI + PI / 4, TWO_PI + PI / 3, TWO_PI + PI / 2, TWO_PI * 2]);

            if (x - fl(r + arcWidth) < 0) {
                x += fl(r + arcWidth) - x;
            }
            if (x + fl(r + arcWidth) > width) {
                x -= fl(r + arcWidth) - (width - x);
            }
            if (y - fl(r + arcWidth) < 0) {
                y += fl(r + arcWidth) - y;
            }
            if (y + fl(r + arcWidth) > height) {
                y -= fl(r + arcWidth) - (height - y);
            }

            if (outlines) {
                push();
                translate(x, y);
                rotate(-angle);
                drawJaggedArc(0, 0, 0, PALETTE.outlineColor, r * 0.94, start, stop, 0.2);
                drawJaggedArc(0, 0, 0, PALETTE.outlineColor, r + arcWidth, start, stop, 0.2);
                pop();
            }

            let c = colors.pop();
            elements.push(new Arc(x, y, angle, r, arcWidth, c, start, stop));
            updateSeed();
            if (colors.length === 0) {
                colors = shuffle([...PALETTE.arcColors]);
            }
        }
        segmentNum++;
    });
    elements.sort((a, b) => (a.getArea() > b.getArea()) ? -1 : ((b.getArea() > a.getArea()) ? 1 : 0))
}


function initRects() {
    let segmentNum = 0;

    let colors = shuffle([...PALETTE.rectColors]);
    segments.forEach(segment => {
        for (let i = 1; i <= numRects[segmentNum]; i++) {
            let x = fl(randomGaussian((segment.x + segment.w * 0.5), segment.w / sdDivider));
            let y = fl(randomGaussian((segment.y + segment.h * 0.5), segment.h / sdDivider));

            let angle = map(noise(x * 0.00001, y * 0.00001, segmentNum * 10), 0, 1, 0, HALF_PI) + random([0, PI / 2]);

            let rW;
            rW = fl(minSide * random(0.74, 0.82) * (i / (numRects[segmentNum])) * (1 - segments.length * 0.14));

            rW = max(rW, minSide * 0.03);
            let rH = fl(rW * random(0.18, 0.32));
            if (rW === minSide * 0.03) {
                rH = fl(rW * random(0.5, 0.8));
            }

            if (x - fl(rW / 2) < fl(width * 0.02)) {
                x += fl(rW / 2) - (x - fl(width * 0.02));
            }
            if (x + fl(rW / 2) > fl(width * 0.98)) {
                x -= fl(rW / 2) - (fl(width * 0.98) - x);
            }
            if (y - fl(rW / 2) < fl(height * 0.02)) {
                y += fl(rW / 2) - (y - fl(height * 0.02));
            }
            if (y + fl(rW / 2) > fl(height * 0.98)) {
                y -= fl(rW / 2) - (fl(height * 0.98) - y);
            }

            if (outlines) {
                push();
                translate(x, y);
                rotate(-angle);
                scale(1.04, 1.1);
                drawJaggedLine(-rW / 2, -rH / 2, 0, rW, PALETTE.outlineColor, 0.2);
                drawJaggedLine(rW / 2, -rH / 2, -PI / 2, rH, PALETTE.outlineColor, 0.2);
                drawJaggedLine(rW / 2, rH / 2, PI, rW, PALETTE.outlineColor, 0.2);
                drawJaggedLine(-rW / 2, rH / 2, PI / 2, rH, PALETTE.outlineColor, 0.2);
                pop();
            }
            let c = colors.pop();
            elements.push(new Rectangle(x, y, angle, rW, rH, c));
            updateSeed();
            if (colors.length === 0) {
                colors = shuffle([...PALETTE.rectColors]);
            }
        }
        segmentNum++;
    });
}



