function initPlacement() {
    function splitSegments(segments) {
        if (segmentCount >= maxSegments) {
            return;
        }
        let segment = segments.pop();
        let splitDirection;
        if ((segment.w < fl(width * minSplitMult)) && (segment.h < fl(height * minSplitMult))) {
            segments.push(segment);
            return;
        } else if ((segment.h < fl(height * minSplitMult)) || ((format !== 1) && (maxSegments < 3))) {
            splitDirection = Split.VERTICAL;
        } else if (segment.w < fl(width * minSplitMult) || ((format !== 2) && (maxSegments < 3))) {
            splitDirection = Split.HORIZONTAL;
        } else {
            splitDirection = random([Split.VERTICAL, Split.HORIZONTAL]);
        }

        segmentCount++;
        switch (splitDirection) {
            case Split.VERTICAL: {
                let leftSplit = random() > 0.5;

                let splitPoint = {
                    x: fl(segment.x + segment.w * random(0.4, 0.6)),
                    y: segment.y
                };
                let leftSegment = {
                    x: segment.x,
                    y: segment.y,
                    w: fl(splitPoint.x - segment.x),
                    h: segment.h
                }
                segments.push(leftSegment);

                if (leftSplit) {
                    splitSegments(segments);
                }

                let rightSegment = {
                    x: splitPoint.x,
                    y: segment.y,
                    w: fl(segment.x + segment.w - splitPoint.x),
                    h: segment.h
                }
                segments.push(rightSegment);

                if (!leftSplit) {
                    splitSegments(segments);
                }

                break;
            }
            case Split.HORIZONTAL: {
                let topSplit = random() > 0.5;
                let splitPoint = {
                    x: segment.x,
                    y: fl(segment.y + segment.h * random(0.4, 0.6))
                };
                let topSegment = {
                    x: segment.x,
                    y: segment.y,
                    w: segment.w,
                    h: fl(splitPoint.y - segment.y)
                }
                segments.push(topSegment);

                if (topSplit) {
                    splitSegments(segments);
                }

                let bottomSegment = {
                    x: segment.x,
                    y: splitPoint.y,
                    w: segment.w,
                    h: fl(segment.y + segment.h - splitPoint.y)
                }
                segments.push(bottomSegment);

                if (!topSplit) {
                    splitSegments(segments);
                }

                break;
            }
        }
    }

    function placement() {
        segmentCount = 1;
        let segments = [];

        let marginMult = 0.06;

        segments.push({
            x: fl(width * marginMult),
            y: fl(height * marginMult),
            w: fl(width * (1 - marginMult * 2)),
            h: fl(height * (1 - marginMult * 2))
        });
        splitSegments(segments);

        return segments;
    }

    segments = placement();
}

function initDots(numOfDots, meanX, sdX, meanY, sdY, dotsColor) {
    let dots = [];
    for (let i = 0; i < numOfDots; i++) {
        dots.push(
            {
                x: randomGaussian(meanX, sdX),
                y: randomGaussian(meanY, sdY),
                r: randomGaussian(0.035, 0.02) * minSide * 0.015,
                c: color(
                    hue(window.color(dotsColor)),
                    saturation(window.color(dotsColor)) * random(0.9, 1.05),
                    brightness(window.color(dotsColor)) * random(0.9, 1.05),
                    random(0.1, 1)
                )
            }
        )
    }
    return dots;
}

