class Rectangle {
    static rectNumber = 0;

    constructor(translateX, translateY, angle, rW, rH, rectColor) {
        Rectangle.rectNumber++;
        this._rectNumber = Rectangle.rectNumber;

        this._translateX = translateX;
        this._translateY = translateY;
        this._angle = angle;
        this._rW = rW;
        this._rH = rH;
        this._rectColor = rectColor;
        this._lines = [];
        this._borderLines = [];
        this._borderDrawn = [false, false];
        this._isDrawn = false;

        this._dotsDrawn = false;
        this._dots = [];

        this.#initLines();
        this.#initDots();
    }

    #initDots() {
        let numOfDots = int(fl(random(70, 200)));
        this._dots.push(...initDots(numOfDots, -this._rW / 2, this._rW / 6,
            0, this._rH / 2, this._rectColor));

        numOfDots = int(fl(random(50, 100)));
        this._dots.push(...initDots(numOfDots, this._rW / 2, this._rW / 8,
            0, this._rH / 3, this._rectColor));
    }

    #initLines() {
        let lineWeightMult = 0.4;
        let startSatMult = random(0.98, 1);
        let space = 0.6;
        let numOfStepsX = int(fl(this._rW / (lineWeightMult * strokeW * space)));
        let numOfStepsY = int(fl(this._rH / (lineWeightMult * strokeW * space)));

        for (let i = 0; i < numOfStepsY; i++) {
            let lineColor = color(
                hue(window.color(this._rectColor)),
                saturation(window.color(this._rectColor)),
                map(abs(numOfStepsY / 2 - i), numOfStepsY / 2, 0, 0.98, 1) * brightness(window.color(this._rectColor))
            );

            this._lines.push(
                new ColoredLine(-this._rW / 2,
                    -this._rH / 2 + lineWeightMult * strokeW * space * i,
                    0,
                    this._rW,
                    lineColor,
                    lineWeightMult, startSatMult)
            );
        }

        let bordersColor = color(hue(window.color(this._rectColor)), saturation(window.color(this._rectColor)) * startSatMult, brightness(window.color(this._rectColor)));

        this._borderLines.push(
            new ColoredLine(-this._rW / 2 + lineWeightMult * strokeW * space * (0.6),
                -this._rH / 2,
                -PI / 2,
                fl(this._rH * 0.94), bordersColor, lineWeightMult, startSatMult)
        );
        this._borderLines.push(
            new ColoredLine(-this._rW / 2 + lineWeightMult * strokeW * space * (numOfStepsX + 1.2),
                -this._rH / 2,
                -PI / 2,
                fl(this._rH * 0.95), bordersColor, lineWeightMult, startSatMult)
        );
    }

    getArea() {
        return this._rH * this._rW;
    }

    #addDots() {
        push();
        noStroke();
        for (let i = 0; i < 20; i++) {
            let x = random(-this._rW * 0.98 / 2, this._rW * 0.98 / 2);
            let y = random(-this._rH * 0.9 / 2, this._rH * 0.9 / 2);
            let d = random(this._rW * 0.004);
            fill(color(
                hue(window.color(this._rectColor)),
                saturation(window.color(this._rectColor))
                * map(noise(x * 0.05, y * 0.05), 0, 1, 0.9, 1.1),
                brightness(window.color(this._rectColor)) * map(noise(x * 0.05, y * 0.05, 3), 0, 1, 0.9, 1.1),
                random(0.4, 0.8)
            ));
            rect(x, y, d);
        }
        pop();
    }


    #drawDots() {
        push();
        noStroke();
        this._dots.forEach(element => {
            fill(element.c);
            circle(element.x, element.y, element.r * 2);
        })
        pop();
    }

    drawPoints() {
        push();
        translate(this._translateX, this._translateY);
        rotate(-this._angle);

        if (!this._dotsDrawn) {
            this.#drawDots();
            this._dotsDrawn = true;
        }

        if (this._rH > fl(minSide * 0.03)) {
            if (!this._borderDrawn[0]) {
                this._borderLines[0].drawWholeLine();
                this._borderDrawn[0] = true;
            }
        }

        if (this._isDrawn) {
            return;
        }

        for (let i = 0; i < drawSpeed; i++) {
            this.#addDots();
            for (let j = 0; j < this._lines.length; j++) {
                this._lines[j].drawLinePoint();
            }
        }

        if (this._rH > fl(minSide * 0.03)) {
            if ((!this._borderDrawn[1]) && (this._lines[0].leftToDraw() <= drawSpeed + 1)) {
                this._borderLines[1].drawWholeLine();
                this._borderDrawn[1] = true;
            }

        }

        if (this._lines[0].isDrawn()) {
            this._isDrawn = true;
        }

        pop();
    }


    isDrawn() {
        return this._isDrawn;
    }
}

/**
 * Abstract class for point object.
 * Point contains color, weight.
 *
 * Child classes must implement drawPoint(x, y) method.
 * */
class LinePoint {
    static lineNumber = 0;

    constructor(baseColor, pointWeight, numOfPoints, startSatMult = 0.9) {
        LinePoint.lineNumber++;
        this._pointWeight = pointWeight;
        this._baseColor = baseColor;
        this._pointNumber = 0;
        this._lineNumber = LinePoint.lineNumber;
        this._numOfPoints = numOfPoints;
        this._startSatMult = startSatMult;
        this._satBoundStart = random(0.1, 0.3);
        this._satBoundEnd = random(0.7, 0.9);
        this._satChangePoint = (this._satBoundStart + this._satBoundEnd) / 2;
    }

    drawPoint(x, y) {
    }
}


/**
 * Class for colored point object.
 * Contains base color, base weight.
 * */
class ColoredPoint extends LinePoint {
    constructor(baseColor, pointWeight, numOfPoints, startSatMult) {
        super(baseColor, pointWeight, numOfPoints, startSatMult);
        this._hueVal = hue(window.color(baseColor));
        this._satVal = saturation(window.color(baseColor));
        this._brightVal = brightness(window.color(baseColor));
    }

    /**
     * Draws a colored point.
     * stepSize between points should be = minSide * 0.0005;
     * @param x
     * @param y
     * */
    drawPoint(x, y) {
        let alphaVal;
        let currentSat;
        let currentBright;
        let currentHue;
        let lineWeight;

        let repeatNum = 3;

        for (let i = 1; i <= repeatNum; i++) {
            currentHue = (this._hueVal + map(noise(this._pointNumber * 0.02, (this._lineNumber + i + 12) * 0.6),
                0, 1, -2, 2)) % 360;

            alphaVal = map(noise(this._pointNumber * 0.02, this._lineNumber + i + 2),
                0, 1, 1, 1 / repeatNum);


            currentSat = map(noise(this._pointNumber * 0.03, (this._lineNumber + i + 1) * 0.5),
                    0, 1, this._satVal * 0.95, this._satVal * 1.05)
                * map(this._pointNumber / this._numOfPoints, 0, this._satBoundStart, this._startSatMult, 1);

            if (this._pointNumber / this._numOfPoints > this._satChangePoint) {
                currentSat = map(noise(this._pointNumber * 0.03, (this._lineNumber + i) * 0.4),
                        0, 1, this._satVal * 0.95, this._satVal * 1.05)
                    * map(this._pointNumber / this._numOfPoints, this._satBoundEnd, 1, 1, this._startSatMult);
            }

            currentBright = map(noise(this._pointNumber * 0.03, (this._lineNumber + i) * 5),
                0, 1, this._brightVal * 0.92, this._brightVal * 1.06);

            lineWeight = this._pointWeight * map(noise(this._pointNumber * 0.04, this._lineNumber + i),
                0, 1, 0.5, 1.1);

            strokeWeight(lineWeight * 1.4);
            stroke(color(currentHue, currentSat, currentBright, alphaVal));
            let shiftY = map(noise(this._pointNumber * 0.02, this._lineNumber + i),
                0, 1, -0.8, 0.8);
            point(x, y + lineWeight * shiftY);
        }
        this._pointNumber++;
    }
}


/**
 * Class for solid-color point with skips.
 * Contains base color, base weight.
 * */
class SkipPoint extends LinePoint {
    constructor(baseColor, pointWeight) {
        super(baseColor, pointWeight);
        this._hueVal = hue(window.color(baseColor));
        this._satVal = saturation(window.color(baseColor));
        this._brightVal = brightness(window.color(baseColor));
    }

    /**
     * Draws a solid-color point with skips (outline).
     * stepSize between points should be = minSide * 0.0002;
     * @param x
     * @param y
     * */
    drawPoint(x, y) {
        if (noise(this._pointNumber * 0.06, LinePoint.lineNumber) < 0.18) {
            this._pointNumber++;
            return;
        }
        let alphaVal = map(noise(this._pointNumber * 0.01, LinePoint.lineNumber),
            0, 1, 0.5, 0.8);
        let lineWeight = this._pointWeight * map(noise(this._pointNumber * 0.001, LinePoint.lineNumber),
            0, 1, 0.3, 1.1);

        stroke(this._hueVal, this._satVal, this._brightVal, alphaVal);
        strokeWeight(lineWeight);

        point(x, y);

        this._pointNumber++;
    }
}


class ColoredLine {
    static lineNumber = 0;

    constructor(translateX, translateY, angle, lineLength, lineColor, lineWeightMult = 0.5, startSatMult = 0.9) {
        ColoredLine.lineNumber++;
        this._translateX = translateX;
        this._translateY = translateY;
        this._angle = angle;
        this._lineLength = lineLength;
        this._lineColor = lineColor;
        this._lineWeightMult = lineWeightMult;
        this._step = 0;
        this._stepSize = minSide * 0.001;
        this._numOfSteps = lineLength / this._stepSize;
        this._x = 0;

        this._lineNumber = ColoredLine.lineNumber;

        let pointWeight = strokeW * this._lineWeightMult;
        this._coloredPoint = new ColoredPoint(this._lineColor, pointWeight, this._numOfSteps, startSatMult);
    }


    isDrawn() {
        return this._step >= this._numOfSteps;
    }
    leftToDraw() {
        return this._numOfSteps - this._step;
    }

    drawLinePoint() {
        if (this._step > this._numOfSteps) {
            return;
        }

        push();
        translate(this._translateX, this._translateY);
        rotate(-this._angle);
        let pointWeight = strokeW * this._lineWeightMult;

        this._x += this._stepSize;
        let y = map(noise(this._step * 0.1, this._lineNumber),
            0, 1, -pointWeight / 10, pointWeight / 10);
        this._coloredPoint.drawPoint(this._x, y);
        this._step++;

        pop();
    }


    drawWholeLine() {
        push();
        translate(this._translateX, this._translateY);
        rotate(-this._angle);
        let x = 0;
        for (let i = 0; i < this._numOfSteps; i++) {
            x += this._stepSize;
            let y = 0;
            this._coloredPoint.drawPoint(x, y);
        }
        pop();
    }
}


class ColoredArc {
    constructor(translateX, translateY, angle,
                r, arcColor, start = 0, stop = PI,
                lineWeightMult = 0.5, startSatMult = 0.9) {
        this._translateX = translateX;
        this._translateY = translateY;
        this._angle = angle;
        this._radius = r;
        this._arcColor = arcColor;
        this._lineWeightMult = lineWeightMult;
        this._step = 0;
        this._stepSize = minSide * 0.001;
        this._numOfSteps = int(abs(stop - start) * r / this._stepSize);

        this._start = start * (-1);
        this._stop = stop * (-1);

        this._angleDiff = -fl((stop - start) / this._numOfSteps);
        let pointWeight = strokeW * this._lineWeightMult;
        this._coloredPoint = new ColoredPoint(this._arcColor, pointWeight, this._numOfSteps, startSatMult);
    }


    isDrawn() {
        return this._step >= this._numOfSteps;
    }

    leftToDraw() {
        return this._numOfSteps - this._step;
    }

    drawArcPoint() {
        if (this._step > this._numOfSteps) {
            return;
        }

        push();
        translate(this._translateX, this._translateY);
        rotate(-this._angle);
        this._coloredPoint.drawPoint(this._radius * cos(this._start + this._angleDiff * this._step),
            this._radius * sin(this._start + this._angleDiff * this._step));
        this._step++;

        pop();
    }


    drawWholeArc() {
        push();
        translate(this._translateX, this._translateY);
        rotate(-this._angle);
        stroke(this._arcColor);
        noFill();

        for (let i = 0; i < this._numOfSteps; i++) {
            this._coloredPoint.drawPoint(this._radius * cos(this._start + this._angleDiff * i),
                this._radius * sin(this._start + this._angleDiff * i));
        }
        pop();
    }
}


/**
 * Draws a jagged line with spaces.
 * @param translateX start x coordinate
 * @param translateY start y coordinate
 * @param angle
 * @param lineLength
 * @param lineColor
 * @param lineWeightMult
 * */
function drawJaggedLine(translateX, translateY, angle, lineLength, lineColor, lineWeightMult = 0.24) {
    push();
    translate(translateX, translateY);
    rotate(-angle);

    let noiseShift = translateX + translateY;
    let stepSize = fl(minSide * 0.0002);
    let numOfSteps = int(lineLength / stepSize);
    let pointWeight = strokeW * lineWeightMult;
    let skipPoint = new SkipPoint(lineColor, pointWeight);

    let x = 0;
    for (let i = 0; i < numOfSteps; i++) {
        x += stepSize;
        let y = map(noise(i * 0.001, noiseShift), 0, 1, -fl(pointWeight * 0.1), fl(pointWeight * 0.1));
        skipPoint.drawPoint(x, y);
    }

    pop();
}


/**
 * Draws arc using skip points.
 * @param translateX start x coordinate
 * @param translateY start y coordinate
 * @param angle
 * @param start start angle
 * @param stop stop angle
 * @param lineColor
 * @param r
 * @param lineWeightMult
 * */
function drawJaggedArc(translateX, translateY, angle, lineColor, r, start = 0, stop = PI, lineWeightMult = 0.26) {
    push();
    translate(translateX, translateY);
    rotate(angle);
    stroke(lineColor);
    noFill();

    start *= -1;
    stop *= -1;

    let stepSize = minSide * 0.0002;
    let numOfSteps = int(abs(stop - start) * r / stepSize);
    let angleDiff = fl((stop - start) / numOfSteps);
    let p = new SkipPoint(lineColor, strokeW * lineWeightMult);

    for (let i = 0; i < numOfSteps; i++) {
        p.drawPoint(fl(r * cos(start + angleDiff * i)) + fl(2 * map(noise(i * 0.001, SkipPoint.lineNumber), 0, 1, -lineWeightMult, lineWeightMult)),
            fl(r * sin(start + angleDiff * i)) + fl(2 * map(noise(i * 0.001, SkipPoint.lineNumber + 1), 0, 1, -lineWeightMult, lineWeightMult)));
    }
    pop();
}

class Arc {
    // max width = 0.2 * minSide
    constructor(translateX, translateY, angle, arcRadius, arcWidth, arcColor,
                start = 0, stop = PI) {
        this._translateX = translateX;
        this._translateY = translateY;
        this._angle = angle;
        this._arcWidth = arcWidth;
        this._arcRadius = arcRadius;
        this._arcColor = arcColor;
        this._start = start;
        this._stop = stop;

        this._lines = [];
        this._borderLines = [];
        this._borderDrawn = [false, false];
        this._isDrawn = false;

        this._dotsDrawn = false;
        this._dots = [];

        this.#initLines();
        this.#initDots();
    }


    #initDots() {
        let numOfDots = int(fl(random(70, 200)));
        this._dots.push(...initDots(numOfDots, this._arcRadius * cos(this._start), this._arcWidth / 2,
            this._arcRadius * sin(this._start), this._arcWidth / 2, this._arcColor));
    }

    #initLines() {
        let lineWeightMult = 0.4;
        let startSatMult = random(0.99, 1);
        let space = 0.6;
        let numOfStepsY = int(fl(this._arcWidth / fl(lineWeightMult * strokeW * space)));

        let shift = 0;

        for (let i = 0; i < numOfStepsY; i++) {
            let currentRadius = this._arcRadius + fl(lineWeightMult * strokeW * space * i);

            if ((this._stop - this._start) >= TWO_PI) {
                shift = random(PI / 6, PI / 2);
            }

            this._lines.push(
                new ColoredArc(0, 0, 0,
                    currentRadius,
                    this._arcColor,
                    this._start,
                    this._stop + shift,
                    lineWeightMult,
                    startSatMult)
            )

        }

        let bordersColor = color(hue(window.color(this._arcColor)), saturation(window.color(this._arcColor)) * startSatMult, brightness(window.color(this._arcColor)));

        this._borderLines.push(
            new ColoredLine(this._arcRadius * 1.03 * cos(this._start),
                -this._arcRadius * 1.02 * sin(this._start),
                this._start + PI / 80,
                fl(this._arcWidth * 0.9), bordersColor, fl(lineWeightMult * 1.4), startSatMult)
        );
        this._borderLines.push(
            new ColoredLine(this._arcRadius * 1.03 * cos(this._stop),
                -this._arcRadius * 1.02 * sin(this._stop),
                this._stop,
                fl(this._arcWidth * 0.9), bordersColor, fl(lineWeightMult * 1.4), startSatMult)
        );
    }

    #drawDots() {
        push();
        noStroke();
        this._dots.forEach(element => {
            fill(element.c);
            circle(element.x, element.y, element.r * 2);
        })
        pop();
    }

    getArea() {
        return fl(sq(fl(this._arcWidth + this._arcRadius)));
    }

    drawPoints() {
        push();
        translate(this._translateX, this._translateY);
        rotate(-this._angle);

        if (!this._dotsDrawn) {
            this.#drawDots();
            this._dotsDrawn = true;
        }

        if (!this._borderDrawn[0]) {
            if (this._arcRadius + this._arcWidth > minSide * 0.04) {
                this._borderLines[0].drawWholeLine();
            }
            this._borderDrawn[0] = true;
        }

        if (this._isDrawn) {
            return;
        }

        for (let j = 0; j < this._lines.length; j++) {
            if (this._lines[j].isDrawn()) {
                continue;
            }
            if ((!this._borderDrawn[1]) && (this._lines[j].leftToDraw() <= drawSpeed + 3)) {
                for (let i = 0; i < drawSpeed / 3; i++) {
                    if (this._arcRadius + this._arcWidth > minSide * 0.04) {
                        this._borderLines[1].drawLinePoint();
                    }
                }
            }
        }

        for (let i = 0; i < drawSpeed; i++) {
            for (let j = 0; j < this._lines.length; j++) {
                this._lines[j].drawArcPoint();
            }
        }

        let isDrawn = true;

        this._lines.forEach(element => {
            if (!element.isDrawn()) {
                isDrawn = false;
            }
        })
        this._isDrawn = isDrawn;
        pop();
    }


    isDrawn() {
        return this._isDrawn;
    }


}
